	protected void addLiveMemoryAndBreakpoint(P process, T target)
    {
		addLiveMemory(process);
		addLiveBreakpoint(target, 0x55550123);
	}

	protected abstract void handleSetBreakpointInvocation(Set<TraceBreakpointKind> expectedKinds,
			long dynOffset);

	protected abstract void handleToggleBreakpointInvocation(
			TraceBreakpointLocation expectedBreakpoint, bool expectedEnabled);

	protected abstract void handleDeleteBreakpointInvocation(T target,
			TraceBreakpointLocation expectedLoc);

	protected void addStaticMemoryAndBreakpoint()
    {
		using (Transaction tx = program.openTransaction("Add bookmark break"))
{
			program.getMemory()
					.createInitializedBlock(".text", addr(program, 0x00400000), 0x1000, (byte) 0,
						TaskMonitor.DUMMY, false);
			program.getBookmarkManager()
					.setBookmark(addr(program, 0x00400123), LogicalBreakpoint.ENABLED_BOOKMARK_TYPE,
						"x;1", "");
		}
	}

	protected void addMapping(Trace trace, Program prog)
    {
		using (Transaction tx = trace.openTransaction("Add mapping"))
{
			DebuggerStaticMappingUtils.addMapping(
				new DefaultTraceLocation(trace, null, Lifespan.nowOn(0), addr(trace, 0x55550000)),
				new ProgramLocation(prog, addr(prog, 0x00400000)), 0x1000, false);
		}
	}

	protected void assertProviderEmpty() {
		assertTrue(breakpointsProvider.breakpointTableModel.getModelData().isEmpty());
		assertTrue(breakpointsProvider.locationTableModel.getModelData().isEmpty());
	}

